script:
root_element.querySelector('#btn-issue').addEventListener('click', function() {
    frappe.new_doc('Stock Entry').then(() => {
        frappe.timeout(0.1).then(() => {
            cur_frm.set_value('stock_entry_type', 'Material Transfer');
            cur_frm.set_value('from_warehouse', 'Facility Stock  - TDt');
            cur_frm.set_value('to_warehouse', 'Employee Tools Issue - TDt');
        });
    });
});

root_element.querySelector('#btn-return').addEventListener('click', function() {
    frappe.new_doc('Stock Entry').then(() => {
        frappe.timeout(0.1).then(() => {
            cur_frm.set_value('stock_entry_type', 'Material Transfer');
            cur_frm.set_value('from_warehouse', 'Employee Tools Issue - TDt');
            cur_frm.set_value('to_warehouse', 'Facility Stock  - TDt');
        });
    });
});

style:
.tools-mgmt {
    padding: 0;
}

.tools-mgmt .tools-buttons {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.tools-mgmt .tool-btn {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 15px;
    border: 1px solid #e2e2e2;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.tools-mgmt .tool-btn:hover {
    background: #f8f9fa;
    border-color: #ccc;
}

.tools-mgmt .btn-icon {
    font-size: 20px;
}

.tools-mgmt .btn-label {
    font-size: 13px;
    font-weight: 500;
    color: #333;
}
